@MainActor public final class PaymentAddressViewModel: PaymentAddressViewModelProtocol {
    public private(set) var state: PaymentAddressFeatureState = .idle
    private let dependencies: PaymentAddressDependencies
    public init(dependencies: PaymentAddressDependencies) { self.dependencies = dependencies }
    public func send(_ event: PaymentAddressEvent) { switch event { case .appeared: state = .loaded; case .retry: state = .loading } }
}

private extension UIColor {
    convenience init(openPencilHex hex: String) {
        let value = hex.trimmingCharacters(in: CharacterSet(charactersIn: "#")); var number: UInt64 = 0; Scanner(string: value).scanHexInt64(&number); let hasAlpha = value.count == 8
        self.init(red: CGFloat((number >> (hasAlpha ? 24 : 16)) & 0xff) / 255, green: CGFloat((number >> (hasAlpha ? 16 : 8)) & 0xff) / 255, blue: CGFloat((number >> (hasAlpha ? 8 : 0)) & 0xff) / 255, alpha: hasAlpha ? CGFloat(number & 0xff) / 255 : 1)
    }
}
